CREATE TABLE `ai_runs` (
  `task` varchar(40) NOT NULL,
  `subject_type` varchar(20) NOT NULL,
  `subject_id` varchar(40) NOT NULL,
  `seller_id` char(36) DEFAULT NULL,
  `inputs` json NOT NULL,
  `output` json NOT NULL,
  `final_text` text NOT NULL,
  `status` varchar(12) NOT NULL,
  `mode` varchar(10) NOT NULL,
  `model` varchar(80) NOT NULL,
  `input_tokens` int NOT NULL,
  `output_tokens` int NOT NULL,
  `cache_creation_tokens` int NOT NULL,
  `cache_read_tokens` int NOT NULL,
  `latency_ms` int NOT NULL,
  `error` varchar(300) NOT NULL,
  `created_by` char(36) DEFAULT NULL,
  `reviewed_by` char(36) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `reviewed_at` datetime(6) DEFAULT NULL,
  `id` char(36) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_ai_runs_created_by_users` (`created_by`),
  KEY `fk_ai_runs_reviewed_by_users` (`reviewed_by`),
  KEY `ix_ai_runs_created_at` (`created_at`),
  KEY `ix_ai_runs_seller_id` (`seller_id`),
  KEY `ix_ai_runs_status` (`status`),
  KEY `ix_ai_runs_task` (`task`),
  KEY `ix_ai_runs_task_created` (`task`,`created_at`),
  CONSTRAINT `fk_ai_runs_created_by_users` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ai_runs_reviewed_by_users` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ai_runs_seller_id_sellers` FOREIGN KEY (`seller_id`) REFERENCES `sellers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `ck_ai_runs_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'applied',_utf8mb4'sent',_utf8mb4'discarded',_utf8mb4'failed')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `ai_runs` WRITE;
