DROP TABLE IF EXISTS `payouts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payouts` (
  `number` varchar(24) NOT NULL,
  `seller_id` char(36) NOT NULL,
  `amount` bigint NOT NULL,
  `status` varchar(12) NOT NULL,
  `mode` varchar(10) NOT NULL,
  `utr` varchar(40) NOT NULL,
  `provider_payout_id` varchar(40) NOT NULL,
  `failure_reason` varchar(300) NOT NULL,
  `bank_snapshot` json NOT NULL,
  `paid_at` datetime(6) DEFAULT NULL,
  `id` char(36) NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT (utc_timestamp(6)),
  `updated_at` datetime(6) NOT NULL DEFAULT (utc_timestamp(6)),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payouts_number` (`number`),
  KEY `ix_payouts_seller_id` (`seller_id`),
  KEY `ix_payouts_status` (`status`),
  CONSTRAINT `fk_payouts_seller_id_sellers` FOREIGN KEY (`seller_id`) REFERENCES `sellers` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_payouts_amount` CHECK ((`amount` > 0)),
  CONSTRAINT `ck_payouts_status` CHECK ((`status` in (_utf8mb4'pending',_utf8mb4'processing',_utf8mb4'paid',_utf8mb4'failed',_utf8mb4'cancelled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

